#include <Arduino.h>
#include <TM1637Display.h>
#include <string.h>

TM1637Display display(4, 5);
unsigned long countOps = 0;
char command[48];
uint8_t commandLen = 0;
unsigned long lastByte = 0;
struct Button {
  uint8_t pin;
  bool raw;
  bool stable;
  unsigned long changed;
};
Button buttons[2] = {{2, HIGH, HIGH, 0}, {3, HIGH, HIGH, 0}};

void showCount() {
  display.showNumberDec((int)(countOps % 10000UL), false);
}
void operate(uint8_t operation) {
  if (operation == 3) {
    countOps = 0;
  } else {
    if (operation == 0) digitalWrite(13, HIGH);
    if (operation == 1) digitalWrite(13, LOW);
    if (operation == 2) tone(6, 1000, 200);
    ++countOps;
  }
  showCount();
}
void dispatch() {
  if (!commandLen) return;
  command[commandLen] = '\0';
  if (strcmp(command, "LIGHT_ON") == 0) operate(0);
  else if (strcmp(command, "LIGHT_OFF") == 0) operate(1);
  else if (strcmp(command, "BEEP") == 0) operate(2);
  else if (strcmp(command, "COUNT_RESET") == 0) operate(3);
  commandLen = 0;
}
void setup() {
  pinMode(2, INPUT_PULLUP);
  pinMode(3, INPUT_PULLUP);
  pinMode(13, OUTPUT);
  pinMode(6, OUTPUT);
  digitalWrite(13, LOW);
  digitalWrite(6, LOW);
  Serial.begin(9600);
  display.setBrightness(7);
  showCount();
}
void loop() {
  while (Serial.available()) {
    char c = (char)Serial.read();
    lastByte = millis();
    if (c == '\n' || c == '\r') dispatch();
    else if (commandLen < sizeof(command) - 1) command[commandLen++] = c;
  }
  unsigned long now = millis();
  if (commandLen && now - lastByte >= 20) dispatch();
  for (uint8_t i = 0; i < 2; ++i) {
    Button &b = buttons[i];
    bool value = digitalRead(b.pin);
    if (value != b.raw) {
      b.raw = value;
      b.changed = now;
    }
    if (value != b.stable && now - b.changed >= 30) {
      b.stable = value;
      if (value == LOW) operate(i);
    }
  }
}
